import React, { useState } from 'react';
import { FaShare, FaBookmark, FaFacebook, FaTwitter, FaLinkedin } from 'react-icons/fa';
import { format } from 'date-fns';

const Newscard = ({ article }) => {
  const [isHovered, setIsHovered] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);

  const handleSave = () => {
    setIsSaved(!isSaved);
  };

  const handleShare = () => {
    setIsShareModalOpen(!isShareModalOpen);
  };

  const handleReadMore = () => {
    // Implement smooth transition to full article view
    console.log('Viewing full article:', article.title);
  };

  return (
    <div
      className={`max-w-sm rounded-lg overflow-hidden shadow-lg transition-all duration-300 ${
        isHovered ? 'transform scale-105' : ''
      }`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <img
        className="w-full h-48 object-cover"
        src={article.imageUrl || 'https://images.unsplash.com/photo-1504711434969-e33886168f5c?ixlib=rb-4.0.3&ixid=M3wxMjA3fDB8MHxwaG90by1wYWdlfHx8fGVufDB8fHx8fA%3D%3D&auto=format&fit=crop&w=1170&q=80'}
        alt={article.title}
      />
      <div className="px-6 py-4">
        <div className="font-bold text-xl mb-2">{article.title}</div>
        <p className="text-gray-700 text-base">{article.summary}</p>
      </div>
      <div className="px-6 pt-4 pb-2 flex justify-between items-center">
        <span className="text-sm text-gray-600">
          {format(new Date(article.publishedAt), 'MMM dd, yyyy')}
        </span>
        <div className="flex space-x-2">
          <button
            onClick={handleShare}
            className="text-blue-500 hover:text-blue-700 focus:outline-none"
            aria-label="Share article"
          >
            <FaShare />
          </button>
          <button
            onClick={handleSave}
            className={`${isSaved ? 'text-yellow-500' : 'text-gray-500'} hover:text-yellow-700 focus:outline-none`}
            aria-label={isSaved ? 'Unsave article' : 'Save article for later'}
          >
            <FaBookmark />
          </button>
        </div>
      </div>
      <div className="px-6 pb-4">
        <button
          onClick={handleReadMore}
          className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline transition duration-300 ease-in-out transform hover:-translate-y-1 hover:scale-110"
        >
          Read More
        </button>
      </div>
      {isShareModalOpen && (
        <div className="absolute top-0 left-0 w-full h-full bg-black bg-opacity-50 flex justify-center items-center">
          <div className="bg-white p-4 rounded-lg">
            <h3 className="font-bold text-lg mb-2">Share Article</h3>
            <div className="flex space-x-4">
              <button className="text-blue-600 hover:text-blue-800">
                <FaFacebook size={24} />
              </button>
              <button className="text-blue-400 hover:text-blue-600">
                <FaTwitter size={24} />
              </button>
              <button className="text-blue-700 hover:text-blue-900">
                <FaLinkedin size={24} />
              </button>
            </div>
            <button
              onClick={() => setIsShareModalOpen(false)}
              className="mt-4 bg-gray-300 hover:bg-gray-400 text-black font-bold py-2 px-4 rounded"
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

